solution:
function solve(dims) {
  const n = dims.length - 1 // jumlah matriks
  const m = Array.from({ length: n }, () => Array(n).fill(0))
  for (let panjang = 2; panjang <= n; panjang++) {
    for (let i = 0; i + panjang - 1 < n; i++) {
      const j = i + panjang - 1
      m[i][j] = Infinity
      for (let k = i; k < j; k++) {
        const biaya =
          m[i][k] + m[k + 1][j] +
          dims[i] * dims[k + 1] * dims[j + 1]
        if (biaya < m[i][j]) m[i][j] = biaya
      }
    }
  }
  return m[0][n - 1]
}
